        for key, value in overlay.items():
            if value is None:
                result.pop(key, None)
            elif isinstance(value, dict) and isinstance(result.get(key), dict):
                result[key] = merge_settings(result[key], (value,))
            else:
                result[key] = copy_value(value)
    return result
